#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int totalInputs, btcFunds;
    std::cin >> totalInputs >> btcFunds;
    std::vector<int> btcDifferences(100, 0);
    int evenCount = 0, oddCount = 0;
    int bufferRight = 0;

    for (int i = 0; i < totalInputs; i++) {
        int currentLeft = 0;
        if (bufferRight == 0) {
            std::cin >> currentLeft;
        } else {
            currentLeft = bufferRight;
            bufferRight = 0;
        }

        if (currentLeft % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (evenCount == oddCount && i != totalInputs - 1) {
            int nextInput;
            std::cin >> nextInput;
            bufferRight = nextInput;
            int diff = std::abs(currentLeft - bufferRight);
            if (diff < 100) {
                btcDifferences[diff] += 1;
            }
            evenCount = 0;
            oddCount = 0;
        }
    }

    int totalSawnCount = 0;
    int totalCostAccum = 0;
    for (int i = 0; i < 100; i++) {
        for (int j = 0; j < btcDifferences[i]; j++) {
            totalCostAccum += i;
            if (totalCostAccum <= btcFunds) {
                totalSawnCount++;
            } else {
                break;
            }
        }
        if (totalCostAccum > btcFunds) {
            break;
        }
    }

    std::cout << totalSawnCount << std::endl;
    return 0;
}

